(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false});
const ui={menu:document.querySelector('#menu'),hud:document.querySelector('#hud'),end:document.querySelector('#end'),prompt:document.querySelector('#prompt'),alert:document.querySelector('#alert'),objective:document.querySelector('#objective'),clock:document.querySelector('#clock'),floor:document.querySelector('#floor'),breath:document.querySelector('#breath'),sound:document.querySelector('#sound')};
let W=0,H=0,frame=0,last=0,gameOn=false,dead=false,paused=false,hasKey=false,day=1,night=0,elapsed=0,alertTime=0,noiseLevel=0,breath=100,hidden=false,hideKind='',sleeping=false,won=false;
const floors=[],props=[],sounds=[],enemies=[];
const player={x:4.5,y:4.5,a:0,z:0,floor:0,walk:0,lean:0,moving:false,run:false,crouch:false,inventory:[]};
const keys={};
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(x,y,X,Y)=>Math.hypot(X-x,Y-y);
let wallTex=[];
function resize(){const d=Math.min(devicePixelRatio||1,1.4);W=canvas.width=Math.floor(innerWidth*d);H=canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.imageSmoothingEnabled=false}
addEventListener('resize',resize);resize();
function makeFloor(f){let n=29,g=Array.from({length:n},()=>Array(n).fill(0));
 // Nine connected, furnished rooms per level; 27 distinct accessible spaces overall.
 for(let ry=0;ry<3;ry++)for(let rx=0;rx<3;rx++){
  const x=1+rx*9,y=1+ry*9;
  for(let i=0;i<7;i++){g[y][x+i]=1;g[y+6][x+i]=1;g[y+i][x]=1;g[y+i][x+6]=1}
  g[y][x+3]=2;g[y+6][x+3]=2;g[y+3][x]=2;g[y+3][x+6]=2;
 }
 // quiet utility stairwell landing sits at the center intersection
 return {g,n,doors:new Map(),floor:f};
}
function initialize(){floors.length=0;props.length=0;sounds.length=0;enemies.length=0;for(let f=0;f<3;f++)floors.push(makeFloor(f));
 const names=[['PATIENT WARD','NURSES’ STATION','LINEN STORAGE','CAFETERIA','WAITING ROOM','PHARMACY','OPERATING THEATRE','RECOVERY','IMAGING'],['MATERNITY WARD','RECORDS','SUPPLY ROOM','INTENSIVE CARE','NURSES’ STATION','MORGUE','THEATRE TWO','LAUNDRY','STAFF ROOM'],['PEDIATRIC WARD','ADMINISTRATION','MAINTENANCE','DAY ROOM','ISOLATION','CLEAN ROOM','LOADING BAY','BOILER ROOM','ARCHIVE']];
 const types=['bed','desk','cabinet','table','chair','gurney','monitor','cart','debris','glass'];
 for(let f=0;f<3;f++)for(let r=0;r<3;r++)for(let c=0;c<3;c++){
  const x=1+c*9,y=1+r*9,id=r*3+c;
  for(let j=0;j<7;j++)for(let i=0;i<7;i++)floors[f].g[y+j][x+i]=0;
  for(let i=0;i<7;i++){floors[f].g[y][x+i]=1;floors[f].g[y+6][x+i]=1;floors[f].g[y+i][x]=1;floors[f].g[y+i][x+6]=1}
  floors[f].g[y][x+3]=2;floors[f].g[y+6][x+3]=2;floors[f].g[y+3][x]=2;floors[f].g[y+3][x+6]=2;
  const roomName=names[f][id];
  // Every room gets several solid, moveable props, not just painted decoration.
  const set=[['bed',x+2.1,y+2.0],['cabinet',x+4.4,y+2.0],['desk',x+2.3,y+4.4],['chair',x+4.6,y+4.4],['cart',x+3.3,y+3.1],['debris',x+1.4,y+4.8]];
  set.forEach(([type,px,py],j)=>props.push({type,x:px+rand(-.18,.18),y:py+rand(-.16,.16),floor:f,room:roomName,solid:['bed','cabinet','desk','cart'].includes(type),movable:['chair','cart'].includes(type),active:true,id:`${f}-${id}-${j}`}));
  if((f===0&&id===0)||(f===1&&id===5)||(f===2&&id===7))props.push({type:'glass',x:x+rand(2,5),y:y+rand(2,5),floor:f,room:roomName,solid:false,active:true,id:`glass-${f}-${id}`});
 }
 // Critical service key is somewhere in the upper floors; loading-bay exit on level 3.
 props.push({type:'key',x:22.3,y:4.5,floor:1,room:'MORGUE',solid:false,active:true,id:'service-key'});
 props.push({type:'exit',x:4.5,y:22.5,floor:2,room:'LOADING BAY',solid:false,active:true,id:'exit'});
 player.x=4.5;player.y=4.5;player.a=.16;player.floor=0;player.z=0;player.inventory=[];player.walk=0;player.lean=0;hasKey=false;day=1;night=0;elapsed=0;dead=false;hidden=false;sleeping=false;won=false;noiseLevel=0;breath=100;
 // A Pale One patrols each level. They investigate remembered sound locations, not the player position.
 for(let f=0;f<3;f++){const spots=[[21.5,21.5],[4.5,22.4],[22.4,4.5]][f];enemies.push({x:spots[0],y:spots[1],floor:f,a:rand(0,6.28),state:'roam',tx:spots[0],ty:spots[1],timer:rand(1,5),speed:rand(.8,1.05),alert:0,attack:0,anim:rand(0,10),bump:0})}
 updateUI();
}
function createTextures(){wallTex=[];for(let k=0;k<4;k++){const t=document.createElement('canvas');t.width=t.height=128;const c=t.getContext('2d');
 const base=['#484b46','#41433f','#383b38','#494841'][k];c.fillStyle=base;c.fillRect(0,0,128,128);
 if(k===0){c.fillStyle='#565953';for(let y=0;y<128;y+=32){c.fillRect(0,y,128,1);for(let x=(y%64?0:32);x<128;x+=64)c.fillRect(x,y,1,32)}c.fillStyle='rgba(12,15,14,.32)';c.fillRect(0,0,128,8)}
 if(k===1){c.strokeStyle='#6b6b61';c.lineWidth=2;for(let y=12;y<128;y+=28){c.beginPath();c.moveTo(0,y);c.lineTo(128,y);c.stroke()}c.fillStyle='#302f2b';c.fillRect(0,0,128,8);for(let x=14;x<128;x+=42){c.fillStyle='#858273';c.fillRect(x,18,3,5)}}
 if(k===2){c.fillStyle='#53554e';c.fillRect(0,0,128,24);c.fillStyle='#282d2c';c.fillRect(0,24,128,104);for(let x=0;x<128;x+=32){c.fillStyle='#424640';c.fillRect(x,28,2,100)}}
 if(k===3){c.fillStyle='#56554b';for(let y=0;y<128;y+=32)c.fillRect(0,y,128,2);c.fillStyle='#30332f';c.fillRect(0,4,128,3);c.fillRect(0,68,128,2)}
 // stains, scratches and damp age
 for(let i=0;i<500;i++){let x=Math.random()*128,y=Math.random()*128;c.fillStyle=Math.random()>.5?'rgba(0,0,0,.13)':'rgba(190,185,165,.035)';c.fillRect(x,y,rand(1,4),rand(1,6))}for(let i=0;i<7;i++){c.fillStyle='rgba(21,27,25,.18)';c.beginPath();c.ellipse(rand(0,128),rand(0,128),rand(4,24),rand(3,14),0,0,7);c.fill()}
 wallTex.push(t)}
}
function cell(x,y,f=player.floor){const g=floors[f].g,ix=Math.floor(x),iy=Math.floor(y);if(ix<0||iy<0||ix>=29||iy>=29)return 1;return g[iy][ix]}
function doorOpen(x,y){return floors[player.floor].doors.get(`${x},${y}`)>0}
function solidAt(x,y,f=player.floor){const xx=Math.floor(x),yy=Math.floor(y),v=cell(x,y,f);if(v===1)return true;if(v===2&&floors[f].doors.get(`${xx},${yy}`)>.72)return false;if(v===2)return true;return props.some(p=>p.active&&p.floor===f&&p.solid&&dist(x,y,p.x,p.y)<(p.type==='bed'?.58:.34))}
function wallish(x,y,f){let v=cell(x,y,f);return v===1||(v===2&&(!floors[f].doors.has(`${Math.floor(x)},${Math.floor(y)}`)||floors[f].doors.get(`${Math.floor(x)},${Math.floor(y)}`)<.72))}
function cast(){const f=player.floor;let horizon=H*.49+player.z,view=player.a+player.lean*.18;const fov=Math.PI*.36,cols=Math.ceil(W/2),step=fov/cols,depth=new Float32Array(cols);ctx.fillStyle='#141817';ctx.fillRect(0,0,W,H/2);ctx.fillStyle='#292924';ctx.fillRect(0,H/2,W,H/2);
 // gloomy ceiling and checker-stained floor wash
 const ceil=ctx.createLinearGradient(0,0,0,horizon);ceil.addColorStop(0,'#090d0d');ceil.addColorStop(1,'#252824');ctx.fillStyle=ceil;ctx.fillRect(0,0,W,horizon);
 const floorGrad=ctx.createLinearGradient(0,horizon,0,H);floorGrad.addColorStop(0,'#37362e');floorGrad.addColorStop(.24,'#252722');floorGrad.addColorStop(1,'#080a09');ctx.fillStyle=floorGrad;ctx.fillRect(0,horizon,W,H-horizon);
 for(let col=0;col<cols;col++){const a=view-fov/2+col*step,rayX=Math.cos(a),rayY=Math.sin(a),mapX=Math.floor(player.x),mapY=Math.floor(player.y);let side=0,hit=0,distSideX,distSideY;const deltaX=Math.abs(1/rayX),deltaY=Math.abs(1/rayY);let sx,sy;if(rayX<0){sx=-1;distSideX=(player.x-mapX)*deltaX}else{sx=1;distSideX=(mapX+1-player.x)*deltaX}if(rayY<0){sy=-1;distSideY=(player.y-mapY)*deltaY}else{sy=1;distSideY=(mapY+1-player.y)*deltaY}
  for(let i=0;i<80;i++){if(distSideX<distSideY){distSideX+=deltaX;mapX+=sx;side=0}else{distSideY+=deltaY;mapY+=sy;side=1}if(mapX<0||mapY<0||mapX>=29||mapY>=29){hit=1;break}let v=floors[f].g[mapY][mapX];if(v===1){hit=1;break}if(v===2){let op=floors[f].doors.get(`${mapX},${mapY}`)||0;if(op<.72){hit=2;break}}
  }
  let d=Math.max(.08,side===0?(mapX-player.x+(1-sx)/2)/rayX:(mapY-player.y+(1-sy)/2)/rayY);d*=Math.cos(a-view);depth[col]=d;
  if(hit){let line=Math.min(H*2,H/d),top=Math.floor(horizon-line/2),wallX=side===0?player.y+d*rayY:player.x+d*rayX;wallX-=Math.floor(wallX);let tex=hit===2?wallTex[2]:wallTex[(mapX*3+mapY*5+f)%4];let tx=Math.floor(wallX*128);if(side===0&&rayX>0||side===1&&rayY<0)tx=127-tx;ctx.drawImage(tex,tx,0,1,128,col*2,top,2,line);let shade=clamp(.87-d*.045-(side?.18:0),.16,.88);ctx.fillStyle=`rgba(5,8,7,${1-shade})`;ctx.fillRect(col*2,top,2,line)}
  if(col%32===0&&d<5){let y=horizon+H*.28/d;ctx.fillStyle='rgba(173,162,129,.045)';ctx.fillRect(col*2,y,64,1)}
 }
 drawSprites(depth,cols,horizon);drawAtmosphere(horizon);
}

function drawSprites(depth,cols,horizon){let list=[];for(const p of props)if(p.active&&p.floor===player.floor)list.push({...p,kind:'prop'});for(const e of enemies)if(e.floor===player.floor)list.push({...e,kind:'enemy'});list.sort((a,b)=>dist(player.x,player.y,b.x,b.y)-dist(player.x,player.y,a.x,a.y));const fov=Math.PI*.72,view=player.a+player.lean*.18,focal=W/(2*Math.tan(fov/2));
 for(const o of list){let dx=o.x-player.x,dy=o.y-player.y,d=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)-view;while(ang>Math.PI)ang-=Math.PI*2;while(ang< -Math.PI)ang+=Math.PI*2;if(Math.abs(ang)>fov/2+.24||d<.2)continue;let sx=W/2+Math.tan(ang)*focal,scale=focal/d,base=horizon+H*.08/d,sz=H/d*(o.kind==='enemy'?1.1:o.type==='bed'?.48:o.type==='debris'?.14:.43),screenCol=Math.floor(sx/2);if(screenCol>=0&&screenCol<cols&&depth[screenCol]<d-.15)continue;
  if(o.kind==='enemy')drawPale(sx,base,sz,o,d);else drawProp(sx,base,sz,o,d);
 }
}
function drawProp(x,base,s,o,d){ctx.save();ctx.translate(x,base);let w=s*(o.type==='bed'?1.7:o.type==='cabinet'?.78:1.0),h=s*(o.type==='bed'?.65:o.type==='chair'?.82:o.type==='debris'?.24:.8);ctx.globalAlpha=clamp(1.05-d*.045,.32,.94);
 // grounding shadow
 ctx.fillStyle='rgba(0,0,0,.68)';ctx.beginPath();ctx.ellipse(0,0,w*.58,Math.max(2,h*.11),0,0,Math.PI*2);ctx.fill();
 const fill=(c)=>{ctx.fillStyle=c;ctx.fillRect(-w/2,-h,w,h)};
 if(o.type==='bed'){fill('#55564f');ctx.fillStyle='#77776c';ctx.fillRect(-w*.5,-h*.42,w,h*.36);ctx.fillStyle='#a5a08e';ctx.fillRect(-w*.44,-h*.54,w*.28,h*.18);ctx.fillStyle='#343832';ctx.fillRect(-w*.5,-h*.1,w,h*.12);ctx.fillStyle='#232724';ctx.fillRect(-w*.45,-h*.03,w*.08,h*.2);ctx.fillRect(w*.37,-h*.03,w*.08,h*.2)}
 else if(o.type==='cabinet'){fill('#51534d');ctx.strokeStyle='#858273';ctx.lineWidth=Math.max(1,w*.025);ctx.strokeRect(-w*.42,-h*.91,w*.84,h*.84);ctx.beginPath();ctx.moveTo(0,-h*.91);ctx.lineTo(0,-h*.06);ctx.stroke();ctx.fillStyle='#aaa58f';ctx.fillRect(-w*.1,-h*.5,w*.06,h*.06);ctx.fillRect(w*.04,-h*.5,w*.06,h*.06)}
 else if(o.type==='desk'||o.type==='table'){fill('#555247');ctx.fillStyle='#716c5c';ctx.fillRect(-w*.55,-h*.42,w*1.1,h*.16);ctx.fillStyle='#343731';ctx.fillRect(-w*.46,-h*.28,w*.08,h*.27);ctx.fillRect(w*.38,-h*.28,w*.08,h*.27);ctx.fillStyle='#9d9a8d';ctx.fillRect(-w*.15,-h*.63,w*.3,h*.2)}
 else if(o.type==='chair'){ctx.fillStyle='#494b45';ctx.fillRect(-w*.38,-h*.8,w*.76,h*.35);ctx.fillRect(-w*.38,-h*.95,w*.76,h*.18);ctx.fillRect(-w*.32,-h*.45,w*.1,h*.45);ctx.fillRect(w*.22,-h*.45,w*.1,h*.45)}
 else if(o.type==='cart'||o.type==='gurney'){fill('#555951');ctx.fillStyle='#a19d89';ctx.fillRect(-w*.52,-h*.82,w*1.04,h*.13);ctx.fillStyle='#9e9d8e';ctx.fillRect(-w*.44,-h*.69,w*.04,h*.55);ctx.fillRect(w*.4,-h*.69,w*.04,h*.55);ctx.fillStyle='#171c1a';ctx.beginPath();ctx.arc(-w*.3,-h*.04,h*.09,0,7);ctx.arc(w*.3,-h*.04,h*.09,0,7);ctx.fill()}
 else if(o.type==='debris'||o.type==='glass'){ctx.fillStyle=o.type==='glass'?'rgba(181,200,189,.75)':'#66645a';for(let i=0;i<5;i++){ctx.beginPath();let xx=rand(-w/2,w/2),yy=rand(-h,h*.05);ctx.moveTo(xx,yy);ctx.lineTo(xx+rand(2,w*.3),yy-rand(2,h*.4));ctx.lineTo(xx+rand(-w*.2,w*.2),yy+rand(1,h*.12));ctx.fill()}}
 else if(o.type==='key'){ctx.fillStyle='#d5bc72';ctx.fillRect(-w*.16,-h*.55,w*.32,h*.2);ctx.fillRect(w*.05,-h*.39,w*.09,h*.22);ctx.fillStyle='#e2d49a';ctx.beginPath();ctx.arc(-w*.05,-h*.55,w*.1,0,7);ctx.fill()}
 else if(o.type==='exit'){ctx.fillStyle='#242a27';ctx.fillRect(-w*.75,-h*1.7,w*1.5,h*1.7);ctx.strokeStyle='#77776c';ctx.lineWidth=Math.max(1,w*.04);ctx.strokeRect(-w*.75,-h*1.7,w*1.5,h*1.7);ctx.fillStyle='#b1473c';ctx.font=`${Math.max(7,w*.16)}px monospace`;ctx.textAlign='center';ctx.fillText('EXIT',0,-h*1.38);ctx.fillStyle='#b4a987';ctx.fillRect(w*.45,-h*.75,w*.07,h*.07)}
 ctx.restore();}
function drawPale(x,base,size,e,d){ctx.save();ctx.translate(x,base);ctx.globalAlpha=clamp(1.15-d*.035,.4,1);const s=size, wob=Math.sin(e.anim*8)*s*.018, scaleX=e.state==='attack'?1.12:1;ctx.scale(scaleX,1);ctx.translate(0,wob);
 ctx.fillStyle='rgba(0,0,0,.78)';ctx.beginPath();ctx.ellipse(0,0,s*.48,s*.12,0,0,7);ctx.fill();
 // low, elongated quadruped silhouette. Knobby limbs collide with the world around it.
 ctx.strokeStyle='#7f827d';ctx.lineWidth=s*.105;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-s*.12,-s*.5);ctx.lineTo(-s*.43,-s*.21);ctx.lineTo(-s*.5,-s*.06);ctx.moveTo(s*.1,-s*.49);ctx.lineTo(s*.4,-s*.2);ctx.lineTo(s*.52,-s*.04);ctx.moveTo(-s*.12,-s*.37);ctx.lineTo(-s*.35,-s*.09);ctx.lineTo(-s*.34,-s*.01);ctx.moveTo(s*.1,-s*.36);ctx.lineTo(s*.34,-s*.12);ctx.lineTo(s*.39,-s*.02);ctx.stroke();
 const g=ctx.createLinearGradient(-s*.3,-s*.9,s*.3,-s*.13);g.addColorStop(0,'#d3d2c8');g.addColorStop(.4,'#aaa99e');g.addColorStop(1,'#686d68');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,-s*.4,s*.3,s*.43,-.1,0,7);ctx.fill();ctx.beginPath();ctx.ellipse(s*.08,-s*.78,s*.2,s*.23,0,0,7);ctx.fill();
 // completely blank, taut face; only an impossible black mouth when close/attacking
 ctx.fillStyle='#bdbbb0';ctx.beginPath();ctx.ellipse(s*.09,-s*.78,s*.15,s*.16,0,0,7);ctx.fill();if(e.state==='attack'||e.attack>0){ctx.fillStyle='#080909';ctx.beginPath();ctx.ellipse(s*.09,-s*.77,s*.12,s*.19,0,0,7);ctx.fill();ctx.strokeStyle='#dedbd0';ctx.lineWidth=s*.015;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(s*(-.005+i*.045),-s*.88);ctx.lineTo(s*(-.005+i*.045),-s*.84);ctx.stroke();ctx.beginPath();ctx.moveTo(s*(-.005+i*.045),-s*.66);ctx.lineTo(s*(-.005+i*.045),-s*.71);ctx.stroke()}}
 // waxy mottled skin noise
 ctx.globalAlpha*=.25;for(let i=0;i<25;i++){ctx.fillStyle=i%2?'#e4e0d4':'#343a37';ctx.beginPath();ctx.arc(rand(-s*.2,s*.2),rand(-s*.9,-s*.2),s*rand(.008,.025),0,7);ctx.fill()}
 ctx.restore();}
function drawAtmosphere(h){const pulse=.025+Math.sin(frame*.037)*.012;let grad=ctx.createRadialGradient(W*.5,h*.84,10,W*.5,h*.8,W*.65);grad.addColorStop(0,'rgba(173,164,132,0)');grad.addColorStop(.7,`rgba(120,111,85,${pulse})`);grad.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);if(alertTime>0){ctx.fillStyle=`rgba(110,20,16,${Math.min(.11,alertTime*.025)})`;ctx.fillRect(0,0,W,H)}
 // first-person sleeve and trembling fingers
 if(!hidden&&!dead){ctx.save();ctx.globalAlpha=.72;let bob=Math.sin(player.walk*7)*4;ctx.fillStyle='#252925';ctx.beginPath();ctx.moveTo(W*.42,H);ctx.lineTo(W*.44,H*.88+bob);ctx.lineTo(W*.50,H*.9+bob);ctx.lineTo(W*.53,H);ctx.fill();ctx.fillStyle='#827f72';ctx.beginPath();ctx.ellipse(W*.475,H*.9+bob,12,24,-.2,0,7);ctx.fill();ctx.restore()}}

function emit(x,y,intensity,kind='movement'){sounds.push({x,y,floor:player.floor,power:intensity,kind,age:0});noiseLevel=Math.max(noiseLevel,intensity);alertTime=Math.max(alertTime,intensity>.45?1.2:.25);}
function roomAt(x,y){const rx=Math.floor((x-1)/9),ry=Math.floor((y-1)/9);if(rx<0||ry<0||rx>2||ry>2)return 'CORRIDOR';return ['PATIENT WARD','NURSES’ STATION','LINEN STORAGE','CAFETERIA','WAITING ROOM','PHARMACY','OPERATING THEATRE','RECOVERY','IMAGING'][ry*3+rx]}
function nearTarget(){let best=null,bd=2.0;for(const p of props){if(!p.active||p.floor!==player.floor)continue;let d=dist(player.x,player.y,p.x,p.y),a=Math.atan2(p.y-player.y,p.x-player.x)-player.a;while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;if(d<bd&&Math.abs(a)<.75){best=p;bd=d}}
 let door=null,dd=1.8;for(let y=0;y<29;y++)for(let x=0;x<29;x++)if(cell(x+.5,y+.5)===2){let d=dist(player.x,player.y,x+.5,y+.5),a=Math.atan2(y+.5-player.y,x+.5-player.x)-player.a;while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;if(d<dd&&Math.abs(a)<.55){door={x,y,d};dd=d}}
 if(door&&(!best||dd<bd))return {type:'door',...door};return best?{type:'prop',p:best,d:bd}:null;
}
function updatePrompt(){if(!gameOn||hidden||dead){ui.prompt.classList.remove('show');return}const t=nearTarget();if(!t){ui.prompt.classList.remove('show');return}let text='';if(t.type==='door')text=(floors[player.floor].doors.get(`${t.x},${t.y}`)>.72?'E  CLOSE DOOR':'E  PUSH DOOR');else{let p=t.p;text=p.type==='key'?'E  TAKE SERVICE KEY':p.type==='exit'?(hasKey?'E  UNLOCK LOADING BAY':'EXIT LOCKED — SERVICE KEY REQUIRED'):p.type==='bed'?(night>0?'E  HIDE / SLEEP':'E  HIDE UNDER BED'):p.type==='cabinet'?'E  SEARCH / HIDE':p.type==='chair'?'E  MOVE CHAIR':p.type==='cart'?'E  MOVE MEDICAL CART':p.type==='glass'?'BROKEN GLASS — STEP CAREFULLY':'E  SEARCH '+p.room}
 ui.prompt.textContent=text;ui.prompt.classList.add('show');}
