function pathStep(e,tx,ty,dt,speed){let gx=Math.floor(e.x),gy=Math.floor(e.y),sx=Math.floor(tx),sy=Math.floor(ty),g=floors[e.floor].g,queue=[[gx,gy]],seen=new Map([[`${gx},${gy}`,null]]),dirs=[[1,0],[-1,0],[0,1],[0,-1]],found=false;
 while(queue.length&&queue.length<1000){let [x,y]=queue.shift();if(x===sx&&y===sy){found=true;break}for(const [dx,dy] of dirs){let nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=29||ny>=29)continue;let v=g[ny][nx],key=`${nx},${ny}`;if(v===1||seen.has(key))continue;seen.set(key,[x,y]);queue.push([nx,ny])}}
 let txc=sx,tyc=sy;if(found){let cur=[sx,sy];while(seen.get(`${cur[0]},${cur[1]}`)&&!(seen.get(`${cur[0]},${cur[1]}`)[0]===gx&&seen.get(`${cur[0]},${cur[1]}`)[1]===gy))cur=seen.get(`${cur[0]},${cur[1]}`);txc=cur[0];tyc=cur[1]}
 let v=cell(txc+.5,tyc+.5,e.floor);if(v===2){floors[e.floor].doors.set(`${txc},${tyc}`,1);if(e.state==='hunt'&&Math.random()<dt*.5)emit(e.x,e.y,.17,'door scrape')}
 let dx=txc+.5-e.x,dy=tyc+.5-e.y,d=Math.hypot(dx,dy);if(d<.16){dx=tx-e.x;dy=ty-e.y;d=Math.hypot(dx,dy)}if(d>.01){let vx=dx/d*speed*dt,vy=dy/d*speed*dt;if(!solidAt(e.x+vx,e.y,e.floor))e.x+=vx;else if(!solidAt(e.x,e.y+vy,e.floor))e.y+=vy;else{e.bump+=dt;if(e.bump>1){let alt=dirs[Math.floor(Math.random()*4)];if(!solidAt(e.x+alt[0]*.3,e.y+alt[1]*.3,e.floor)){e.x+=alt[0]*.3;e.y+=alt[1]*.3}e.bump=0}}e.a=Math.atan2(dy,dx)}return d;
}
function wallAttenuation(sx,sy,ex,ey,f){let n=18,loss=0;for(let i=1;i<n;i++){let t=i/n;if(cell(sx+(ex-sx)*t,sy+(ey-sy)*t,f)===1)loss+=.11}return loss}
function aiStep(dt){for(const s of sounds)s.age+=dt;sounds.splice(0,sounds.length,...sounds.filter(s=>s.age<13));for(const e of enemies){e.anim+=dt;e.timer-=dt;if(e.floor!==player.floor)continue;
