  let best=null,bscore=0;for(const s of sounds){if(s.floor!==e.floor)continue;let d=dist(e.x,e.y,s.x,s.y),atten=wallAttenuation(e.x,e.y,s.x,s.y,e.floor),score=s.power/(1+d*.16+atten);if(score>.055&&d<26&&score>bscore){bscore=score;best=s}}
  if(best&&bscore>e.alert*.65){e.tx=best.x+rand(-.7,.7);e.ty=best.y+rand(-.7,.7);e.state='hunt';e.timer=rand(7,11);e.alert=bscore;}
  // At close range the creature detects a moving or noisy survivor; a hiding player is not automatically known.
  let dplayer=dist(e.x,e.y,player.x,player.y);if(!hidden&&dplayer<4.2&&player.moving){e.state='hunt';e.tx=player.x+rand(-.35,.35);e.ty=player.y+rand(-.35,.35);e.timer=5;e.alert=.9}
  if(dplayer<.98&&((!hidden&&player.moving)||noiseLevel>.42||e.alert>.48&&dist(e.tx,e.ty,player.x,player.y)<1.1)){e.state='attack';e.attack+=dt;if(e.attack>1.8){dead=true;showEnd(false);return}}else if(e.state==='attack'){e.attack=Math.max(0,e.attack-dt*1.6);if(e.attack===0)e.state='hunt'}
  if(e.state==='roam'){if(e.timer<=0||dist(e.x,e.y,e.tx,e.ty)<.5){e.tx=clamp(Math.floor(e.x/9)*9+rand(2,7),1,27);e.ty=clamp(Math.floor(e.y/9)*9+rand(2,7),1,27);e.timer=rand(3,8)}pathStep(e,e.tx,e.ty,dt,e.speed*.48)}
  else if(e.state==='hunt'){let d=pathStep(e,e.tx,e.ty,dt,e.speed*(night?1.18:1));e.timer-=dt;if(d<.8||e.timer<=0){e.state='search';e.timer=rand(5,9);e.alert*=.55}}
  else if(e.state==='search'){if(e.timer<=0){e.state='roam';e.alert*=.3;e.timer=rand(1,4)}else if(Math.random()<dt*.35){e.tx=clamp(e.x+rand(-2.5,2.5),1,27);e.ty=clamp(e.y+rand(-2.5,2.5),1,27)}pathStep(e,e.tx,e.ty,dt,e.speed*.68)}
 }}
