function emit(x,y,intensity,kind='movement'){sounds.push({x,y,floor:player.floor,power:intensity,kind,age:0});noiseLevel=Math.max(noiseLevel,intensity);alertTime=Math.max(alertTime,intensity>.45?1.2:.25)}
function nearTarget(){if(dist(player.x,player.y,17.5,17.5)<1.15)return{type:'stairs'};let best=null,bd=2;for(let p of props)if(p.active&&p.floor===player.floor){let d=dist(player.x,player.y,p.x,p.y),a=Math.atan2(p.y-player.y,p.x-player.x)-player.a;while(a>Math.PI)a-=2*Math.PI;while(a< -Math.PI)a+=2*Math.PI;if(d<bd&&Math.abs(a)<.75){best=p;bd=d}}let door=null,dd=1.8;for(let y=0;y<29;y++)for(let x=0;x<29;x++)if(cell(x+.5,y+.5)===2){let d=dist(player.x,player.y,x+.5,y+.5),a=Math.atan2(y+.5-player.y,x+.5-player.x)-player.a;while(a>Math.PI)a-=2*Math.PI;while(a< -Math.PI)a+=2*Math.PI;if(d<dd&&Math.abs(a)<.55){door={x,y,d};dd=d}}if(door&&(!best||dd<bd))return{type:'door',...door};return best?{type:'prop',p:best,d:bd}:null}
function updatePrompt(){if(!gameOn||hidden||dead){ui.prompt.classList.remove('show');return}let t=nearTarget();if(!t){ui.prompt.classList.remove('show');return}let text='';if(t.type==='stairs')text='E  TAKE THE STAIRWELL · LEVEL '+(player.floor+1)+' / 3';else if(t.type==='door')text=(floors[player.floor].doors.get(`${t.x},${t.y}`)>.72?'E  CLOSE DOOR':'E  PUSH DOOR');else{let p=t.p;text=p.type==='key'?'E  TAKE SERVICE KEY':p.type==='exit'?(hasKey?'E  UNLOCK LOADING BAY':'EXIT LOCKED — SERVICE KEY REQUIRED'):p.type==='bed'?(night?'E  HIDE / SLEEP':'E  HIDE UNDER BED'):p.type==='cabinet'?'E  SEARCH / HIDE':p.type==='chair'?'E  MOVE CHAIR':p.type==='cart'?'E  MOVE MEDICAL CART':p.type==='glass'?'BROKEN GLASS — STEP CAREFULLY':'E  SEARCH '+p.room}ui.prompt.textContent=text;ui.prompt.classList.add('show')}
function interact(){if(!gameOn||dead)return;if(hidden){if(!sleeping){hidden=false;emit(player.x,player.y,.42,'rustle')}return}let t=nearTarget();if(!t)return;if(t.type==='stairs'){player.floor=(player.floor+1)%3;emit(player.x,player.y,.42,'footsteps on stairs');updateUI();return}if(t.type==='door'){let k=`${t.x},${t.y}`,op=floors[player.floor].doors.get(k)||0;floors[player.floor].doors.set(k,op>.72?0:1);emit(player.x,player.y,.42,'hinge');return}let p=t.p;if(p.type==='key'){hasKey=true;p.active=false;ui.objective.innerHTML='ESCAPE PLAN<br><b>Reach the loading bay · Level 3</b><br>Stairwell at the central junction';emit(player.x,player.y,.12,'pickup');return}if(p.type==='exit'){if(hasKey){won=true;dead=true;showEnd(true)}else emit(player.x,player.y,.5,'rattle');return}if(p.type==='bed'){if(night){sleeping=true;hidden=true;hideKind='bed';sleepProgress=0;emit(player.x,player.y,.12,'fabric');ui.prompt.textContent='HOLD STILL · SLEEP'}else{hidden=true;hideKind='bed';emit(player.x,player.y,.13,'fabric')}return}if(p.type==='cabinet'){hidden=true;hideKind='cupboard';emit(player.x,player.y,.22,'latch');return}if(p.type==='chair'||p.type==='cart'){let nx=p.x+Math.cos(player.a)*.75,ny=p.y+Math.sin(player.a)*.75;if(!solidAt(nx,ny,p.floor)){p.x=nx;p.y=ny;emit(p.x,p.y,p.type==='cart'?.72:.5,p.type==='cart'?'metal scrape':'scrape')}return}if(p.type==='glass'){emit(p.x,p.y,.9,'glass');p.active=false;return}p.searched=!p.searched;emit(player.x,player.y,p.searched?.18:.3,'drawer');if(p.searched&&Math.random()<.2)player.inventory.push('bandage')}
function showEnd(success){ui.end.classList.remove('hide');document.exitPointerLock?.();document.querySelector('#endtag').textContent=success?'ESCAPED · THREE DAYS':'ATTEMPT ENDED';document.querySelector('#endtitle').textContent=success?'YOU MADE IT OUT':'IT FOUND YOU';document.querySelector('#endtext').textContent=success?'The cold air outside burns your lungs. Behind you, the hospital remains silent. You survived St. Agnes.':'The Pale One opens its impossible mouth. Your last sound is swallowed by the dark. Your attempt ends here.'}
function begin(){initialize();createTextures();gameOn=true;ui.menu.classList.add('hide');ui.end.classList.add('hide');ui.hud.classList.remove('hide');canvas.requestPointerLock?.();last=performance.now();requestAnimationFrame(loop)}document.querySelector('#start').onclick=begin;document.querySelector('#again').onclick=begin;
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyE'&&!e.repeat)interact();if(e.code==='Escape'&&gameOn&&!dead){if(document.pointerLockElement)document.exitPointerLock();else canvas.requestPointerLock?.()}});addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&!hidden)player.a+=e.movementX*.0022});canvas.addEventListener('click',()=>{if(gameOn&&!dead&&!document.pointerLockElement)canvas.requestPointerLock?.()});document.querySelector('#touchmove').addEventListener('touchstart',e=>{e.preventDefault();touchMove=true},{passive:false});document.querySelector('#touchmove').addEventListener('touchend',()=>touchMove=false);document.querySelector('#touchcrouch').addEventListener('touchstart',e=>{e.preventDefault();keys.ControlLeft=true},{passive:false});document.querySelector('#touchcrouch').addEventListener('touchend',()=>keys.ControlLeft=false);document.querySelector('#touchinteract').addEventListener('click',interact);
function collisionMove(dx,dy){if(!solidAt(player.x+dx,player.y))player.x+=dx;if(!solidAt(player.x,player.y+dy))player.y+=dy}
function stepPlayer(dt){if(hidden||sleeping)return;let fw=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(touchMove)fw=1;player.run=(keys.ShiftLeft||keys.ShiftRight)&&!keys.ControlLeft;player.crouch=keys.ControlLeft||keys.ControlRight;let lean=(keys.KeyQ?-1:0)+(keys.KeyR?1:0);player.lean+=(lean-player.lean)*dt*5;let mag=Math.hypot(fw,side);if(mag){fw/=mag;side/=mag}let speed=player.crouch?.85:player.run?3.25:1.75,vx=(Math.cos(player.a)*fw-Math.sin(player.a)*side)*speed*dt,vy=(Math.sin(player.a)*fw+Math.cos(player.a)*side)*speed*dt,moved=false;if(mag){let ox=player.x,oy=player.y;collisionMove(vx,vy);moved=dist(ox,oy,player.x,player.y)>.001;player.walk+=dt*(player.run?12:7);if(moved&&Math.random()<dt*(player.run?3.5:1.2)){let glass=props.some(p=>p.active&&p.type==='glass'&&p.floor===player.floor&&dist(player.x,player.y,p.x,p.y)<1.1);emit(player.x,player.y,glass?.95:player.run?.62:player.crouch?.045:.2,glass?'glass':player.run?'running':'footsteps')}}player.moving=moved;if(player.run&&moved){breath=Math.max(0,breath-dt*11);if(breath<=0)player.run=false}else breath=Math.min(100,breath+dt*5);player.z=moved?Math.sin(player.walk*(player.run?2.3:1.4))*(player.crouch?1.5:player.run?5:2.2):player.z*.86;for(let p of props)if(p.active&&p.floor===player.floor&&p.solid&&dist(player.x,player.y,p.x,p.y)<.45){let a=Math.atan2(player.y-p.y,player.x-p.x);player.x=p.x+Math.cos(a)*.47;player.y=p.y+Math.sin(a)*.47;if(moved&&Math.random()<dt*2)emit(player.x,player.y,.45,p.type==='cart'?'metal knock':'furniture knock')}}

