 for(let s of sounds){if(s.age>9||s.floor!==e.floor)continue;let sd=dist(e.x,e.y,s.x,s.y),reach=2.5+s.power*16;if(sd<reach&&s.power>.035&&(e.state==='roam'||e.state==='search'||sd<3)){e.state='investigate';e.tx=s.x+rand(-.45,.45);e.ty=s.y+rand(-.45,.45);e.alert=Math.max(e.alert,Math.max(3,8-s.age*.45));e.lastSound=s.kind}}
 if(e.state==='hunt'){e.tx=player.x;e.ty=player.y;e.alert=Math.max(e.alert,2);if(d<.78&&!hidden&&!sleeping){e.state='attack';e.attack=1.1;e.timer=.75;alertTime=2;if(e.timer<-.7){dead=true;showEnd(false)}}moveEnemy(e,e.tx,e.ty,e.speed*1.65,dt)}else if(e.state==='attack'){if(d>.95)e.state='hunt';else if(e.timer<=0){dead=true;showEnd(false);e.timer=2}}
 else if(e.state==='investigate'){moveEnemy(e,e.tx,e.ty,e.speed*1.25,dt);if(dist(e.x,e.y,e.tx,e.ty)<.65){e.state='search';e.timer=rand(4,7);e.alert=Math.max(0,e.alert-1)}}else if(e.state==='search'){e.alert=Math.max(0,e.alert-dt);if(e.timer<=0||e.alert<=0){e.state='roam';e.timer=rand(2,5)}}else{if(e.timer<=0||dist(e.x,e.y,e.tx,e.ty)<.7){e.tx=clamp(e.x+rand(-5,5),1,27);e.ty=clamp(e.y+rand(-5,5),1,27);e.timer=rand(3,7)}moveEnemy(e,e.tx,e.ty,e.speed*.55,dt)}e.anim+=dt}}
