function stepPlayer(dt){if(hidden||sleeping)return;let fw=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(touchMove)fw=1;player.run=(keys.ShiftLeft||keys.ShiftRight)&&!keys.ControlLeft;player.crouch=keys.ControlLeft||keys.ControlRight;let lean=(keys.KeyQ?-1:0)+(keys.KeyR?1:0);player.lean+=(lean-player.lean)*dt*5;let mag=Math.hypot(fw,side);if(mag){fw/=mag;side/=mag}let speed=player.crouch?.85:player.run?3.25:1.75,vx=(Math.cos(player.a)*fw-Math.sin(player.a)*side)*speed*dt,vy=(Math.sin(player.a)*fw+Math.cos(player.a)*side)*speed*dt,moved=false;if(mag){let ox=player.x,oy=player.y;collisionMove(vx,vy);moved=dist(ox,oy,player.x,player.y)>.001;player.walk+=dt*(player.run?12:7);if(moved&&Math.random()<dt*(player.run?3.5:1.2)){let glass=props.some(p=>p.active&&p.type==='glass'&&p.floor===player.floor&&dist(player.x,player.y,p.x,p.y)<1.1);emit(player.x,player.y,glass?.95:player.run?.62:player.crouch?.045:.2,glass?'glass':player.run?'running':'footsteps')}}player.moving=moved;if(player.run&&moved){breath=Math.max(0,breath-dt*11);if(breath<=0)player.run=false}else breath=Math.min(100,breath+dt*5);player.z=moved?Math.sin(player.walk*(player.run?2.3:1.4))*(player.crouch?1.5:player.run?5:2.2):player.z*.86;for(let p of props)if(p.active&&p.floor===player.floor&&p.solid&&dist(player.x,player.y,p.x,p.y)<.45){let a=Math.atan2(player.y-p.y,player.x-p.x);player.x=p.x+Math.cos(a)*.47;player.y=p.y+Math.sin(a)*.47;if(moved&&Math.random()<dt*2)emit(player.x,player.y,.45,p.type==='cart'?'metal knock':'furniture knock')}}
function blockedForAI(x,y,f){let v=cell(x+.5,y+.5,f);if(v===1)return true;if(v===2&&(floors[f].doors.get(`${x},${y}`)||0)<.72)return false;return props.some(p=>p.active&&p.floor===f&&p.solid&&dist(x+.5,y+.5,p.x,p.y)<.48)}
function route(e,tx,ty){let sx=clamp(Math.floor(e.x),0,28),sy=clamp(Math.floor(e.y),0,28),gx=clamp(Math.floor(tx),0,28),gy=clamp(Math.floor(ty),0,28),start=sy*29+sx,goal=gy*29+gx;if(start===goal)return{x:tx,y:ty};let q=[start],prev=new Int32Array(841);prev.fill(-2);prev[start]=-1;let found=false;for(let i=0;i<q.length&&i<841;i++){let id=q[i];if(id===goal){found=true;break}let x=id%29,y=(id/29)|0;for(let [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]){if(nx<0||ny<0||nx>=29||ny>=29)continue;let ni=ny*29+nx;if(prev[ni]!==-2||blockedForAI(nx,ny,e.floor))continue;prev[ni]=id;q.push(ni)}}if(!found)return null;let id=goal;while(prev[id]!==start&&prev[id]>=0)id=prev[id];return{x:id%29+.5,y:((id/29)|0)+.5}}
function visible(ax,ay,bx,by,f){let n=Math.ceil(dist(ax,ay,bx,by)*4);for(let i=1;i<n;i++){let t=i/n;if(cell(ax+(bx-ax)*t,ay+(by-ay)*t,f)===1)return false}return true}
function moveEnemy(e,tx,ty,speed,dt){let target=route(e,tx,ty);if(!target)return;let dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy);if(d<.08)return;let step=Math.min(d,speed*dt),nx=e.x+dx/d*step,ny=e.y+dy/d*step,cx=Math.floor(nx),cy=Math.floor(ny);if(cell(nx,e.y,e.floor)===2)floors[e.floor].doors.set(`${cx},${Math.floor(e.y)}`,1);if(cell(e.x,ny,e.floor)===2)floors[e.floor].doors.set(`${Math.floor(e.x)},${cy}`,1);if(!solidAt(nx,e.y,e.floor))e.x=nx;if(!solidAt(e.x,ny,e.floor))e.y=ny;e.a=Math.atan2(dy,dx);e.anim+=dt}
function updateEnemies(dt){for(let e of enemies){e.timer-=dt;e.attack=Math.max(0,e.attack-dt);let same=e.floor===player.floor,d=same?dist(e.x,e.y,player.x,player.y):99,see=same&&!hidden&&!sleeping&&d<7&&visible(e.x,e.y,player.x,player.y,e.floor);if(see&&d<4){e.state='hunt';e.tx=player.x;e.ty=player.y;e.alert=2.5}else if(see&&e.state==='roam'&&d<5){e.state='investigate';e.tx=player.x;e.ty=player.y;e.alert=1.5}
 for(let s of sounds){if(s.age>9||s.floor!==e.floor)continue;let sd=dist(e.x,e.y,s.x,s.y),reach=2.5+s.power*16;if(sd<reach&&s.power>.035&&(e.state==='roam'||e.state==='search'||sd<3)){e.state='investigate';e.tx=s.x+rand(-.45,.45);e.ty=s.y+rand(-.45,.45);e.alert=Math.max(e.alert,Math.max(3,8-s.age*.45));e.lastSound=s.kind}}
 if(e.state==='hunt'){e.tx=player.x;e.ty=player.y;e.alert=Math.max(e.alert,2);if(d<.78&&!hidden&&!sleeping){e.state='attack';e.attack=1.1;e.timer=.75;alertTime=2;if(e.timer<-.7){dead=true;showEnd(false)}}moveEnemy(e,e.tx,e.ty,e.speed*1.65,dt)}else if(e.state==='attack'){if(d>.95)e.state='hunt';else if(e.timer<=0){dead=true;showEnd(false);e.timer=2}}
 else if(e.state==='investigate'){moveEnemy(e,e.tx,e.ty,e.speed*1.25,dt);if(dist(e.x,e.y,e.tx,e.ty)<.65){e.state='search';e.timer=rand(4,7);e.alert=Math.max(0,e.alert-1)}}else if(e.state==='search'){e.alert=Math.max(0,e.alert-dt);if(e.timer<=0||e.alert<=0){e.state='roam';e.timer=rand(2,5)}}else{if(e.timer<=0||dist(e.x,e.y,e.tx,e.ty)<.7){e.tx=clamp(e.x+rand(-5,5),1,27);e.ty=clamp(e.y+rand(-5,5),1,27);e.timer=rand(3,7)}moveEnemy(e,e.tx,e.ty,e.speed*.55,dt)}e.anim+=dt}}
function updateTime(dt){if(sleeping){sleepProgress+=dt*3;if(sleepProgress>=25){sleeping=false;hidden=false;night=0;elapsed=0;nightsSlept++;if(nightsSlept<3)day++;else day=3;emit(player.x,player.y,.08,'morning');ui.prompt.classList.remove('show');if(nightsSlept>=3)ui.objective.innerHTML='ESCAPE PLAN<br><b>Reach the loading bay · Level 3</b><br>Stairwell at the central junction'}return}elapsed+=dt;night=elapsed>=65?1:0;if(elapsed>=90){elapsed=65;night=1}for(let s of sounds)s.age+=dt;let alive=sounds.filter(s=>s.age<10);sounds.length=0;sounds.push(...alive);noiseLevel=Math.max(0,noiseLevel-dt*.24);alertTime=Math.max(0,alertTime-dt);updateEnemies(dt)}
function updateUI(){if(!ui.clock)return;let mins=Math.floor((elapsed/90)*1440+372)%1440,hour=(mins/60)|0,minute=mins%60;ui.clock.textContent=`DAY ${String(day).padStart(2,'0')} · ${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}${night?' · NIGHT':''}`;ui.floor.textContent=['WEST WING · LEVEL 1','EAST WING · LEVEL 2','SERVICE WING · LEVEL 3'][player.floor];ui.breath.style.width=breath+'%';ui.sound.style.width=clamp(noiseLevel*100,0,100)+'%';ui.alert.classList.toggle('show',alertTime>.55);if(sleeping){ui.prompt.textContent=`SLEEPING · ${Math.floor(sleepProgress/25*100)}%`;ui.prompt.classList.add('show')}else updatePrompt()}
function loop(now){if(!gameOn)return;let dt=Math.min(.05,Math.max(0,(now-last)/1000||0));last=now;frame++;if(!dead){stepPlayer(dt);updateTime(dt);if(frame%8===0)updateUI()}cast();if(!dead)requestAnimationFrame(loop);else{gameOn=false;requestAnimationFrame(()=>cast())}}
let nightsSlept=0;resize();
})();

