const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
  const page = await browser.newPage({viewport:{width:1280,height:720}, deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror', e=>errors.push(String(e)));
  page.on('console', m=>{if(m.type()==='error') errors.push(m.text())});
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  console.log('title:', await page.title());
  console.log('menu:', await page.locator('#menu').innerText());
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/latest.jpg',type:'jpeg',quality:90});
  await page.locator('#start').click();
  await page.waitForTimeout(1200);
  console.log('hud visible:', await page.locator('#hud').isVisible());
  console.log('objective:', await page.locator('#objective').innerText());
  console.log('prompt:', await page.locator('#prompt').innerText());
  const canvasStats=await page.locator('#game').evaluate(c=>{const x=c.getContext('2d');const d=x.getImageData(0,0,c.width,c.height).data;let colors=new Set();for(let i=0;i<d.length;i+=160)colors.add(`${d[i]},${d[i+1]},${d[i+2]}`);return {width:c.width,height:c.height,uniqueSampledColors:colors.size}});
  console.log('canvas:',canvasStats);
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/latest.jpg',type:'jpeg',quality:90});
  console.log('errors:',errors);
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

