@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Oswald:wght@400;500&display=swap');
:root{--blood:#b7443c;--paper:#e1ded4;--dim:#8b8b82;--panel:rgba(10,12,12,.82)}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#090c0c;color:var(--paper);font-family:'DM Mono',monospace}
canvas{display:block;width:100%;height:100%;image-rendering:pixelated}
#game{position:fixed;inset:0}
#grain{position:fixed;inset:0;pointer-events:none;opacity:.10;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:screen}
#vignette{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 36%,rgba(0,0,0,.52) 100%),linear-gradient(180deg,rgba(0,0,0,.18),transparent 30%,transparent 75%,rgba(0,0,0,.48)}
#hud{position:fixed;inset:0;pointer-events:none;text-shadow:0 2px 6px #000}
.topbar{position:absolute;top:24px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:flex-start}
.brand{font:500 21px Oswald,sans-serif;letter-spacing:4px}
.brand small{display:block;color:#9b9b91;font:10px 'DM Mono';letter-spacing:2px;margin-top:3px}
.status{text-align:right;font-size:11px;letter-spacing:1px;color:#b9b8ad}
.status strong{color:#e9e5d9;font-weight:400}
.day{color:#cb6258!important}
.bottomleft{position:absolute;left:30px;bottom:28px;display:flex;gap:22px;align-items:end}
.meterlabel{font-size:9px;color:#aaa99e;letter-spacing:1.5px;margin-bottom:6px}
.meter{width:128px;height:3px;background:#484945}
.meter i{height:100%;display:block;background:#b9b6a8;width:100%;transition:width .2s}
.meter.noise i{background:#bd4a3e}
.prompt{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);padding:10px 14px;background:rgba(0,0,0,.55);border-left:2px solid #b74940;font-size:11px;letter-spacing:.7px;opacity:0;transition:opacity .15s}
.prompt.show{opacity:1}
.cross{position:absolute;top:50%;left:50%;width:14px;height:14px;transform:translate(-50%,-50%);opacity:.7}
.cross:before,.cross:after{content:'';position:absolute;background:#ddd;width:1px;height:7px;left:6px}
.cross:after{transform:rotate(90deg)}
.alert{position:absolute;top:23%;left:50%;transform:translateX(-50%);font:500 13px Oswald;letter-spacing:4px;color:#c94c42;opacity:0;transition:opacity .25s}
.alert.on{opacity:1}
.objective{position:absolute;top:90px;left:30px;font-size:10px;color:#b4b1a6;line-height:1.8;letter-spacing:.4px}
.objective b{color:#e5e0d4;font-weight:400}
.panel{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(5,7,7,.82);backdrop-filter:blur(5px);z-index:5}
.card{width:min(640px,90vw);border-top:1px solid #716e62;border-bottom:1px solid #302f2a;padding:44px 48px;background:linear-gradient(130deg,rgba(24,27,26,.95),rgba(8,10,10,.94));box-shadow:0 24px 100px #000}
.eyebrow{font-size:10px;letter-spacing:3px;color:#b24a41}
.title{font:500 clamp(43px,8vw,76px)/.95 Oswald;letter-spacing:2px;margin:17px 0 12px}
.subtitle{font-size:11px;color:#aaa99e;letter-spacing:2px}
.story{max-width:480px;color:#c0beb5;font-size:12px;line-height:1.9;margin:27px 0}
.controls{border-top:1px solid #373833;padding-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:10px 22px;color:#888a82;font-size:10px}
.controls b{color:#ddd9cf;font-weight:400}
.btn{margin-top:30px;border:1px solid #8e3f38;color:#eee8dd;background:#923b34;padding:14px 25px;font:12px 'DM Mono';letter-spacing:2px;cursor:pointer}
.btn:hover{background:#b44940}
.hide{display:none!important}
.mobile{display:none;position:fixed;bottom:14px;right:14px;z-index:3;gap:8px}
.mobile button{background:#101514bb;color:#ddd;border:1px solid #74766e;padding:15px 18px;font:11px monospace}
@media(max-width:700px){.topbar{top:14px;left:15px;right:15px}
.brand{font-size:17px}
.objective{left:15px;top:74px}
.bottomleft{left:15px;bottom:85px}
.mobile{display:flex}
.card{padding:30px 25px}
.controls{font-size:9px}
.story{font-size:11px}
}

